53	        }
54	        int sampleFloor = request.effectiveSampleFloor();
55	        int threshold = request.effectiveFailureThresholdPercent();
56	        String fingerprint = String.join("|", "release.create", request.model(), request.fromVersion(),
57	                request.toVersion(), String.valueOf(request.ratio()), String.valueOf(sampleFloor),
58	                String.valueOf(threshold));
59	        return idempotency.execute(request.requestId(), "release.create", fingerprint, () -> {
60	            long id;
61	            try {
62	                id = releaseRepository.insert(request.model(), request.fromVersion(), request.toVersion(),
63	                        request.ratio(), sampleFloor, threshold);
64	            } catch (DuplicateKeyException e) {
65	                throw ApiException.conflict("ACTIVE_RELEASE_EXISTS", "型号已存在未终结发布单: " + request.model());
66	            }
67	            return ReleaseView.of(findOrder(id));
68	        }, ReleaseView.class);
69	    }
