72	        String fingerprint = String.join("|", "release.expand", String.valueOf(releaseId),
73	                String.valueOf(request.expectedVersion()), String.valueOf(request.ratio()));
74	        return idempotency.execute(request.requestId(), "release.expand", fingerprint, () -> {
75	            ReleaseOrder order = releaseRepository.findByIdForUpdate(releaseId)
76	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在: " + releaseId));
77	            if (order.status() != ReleaseStatus.ACTIVE) {
78	                throw ApiException.conflict("RELEASE_NOT_ACTIVE",
79	                        "发布单状态为 " + order.status() + "，不能扩量");
80	            }
