67	    @BeforeEach
68	    void setUp() {
69	        jdbc.update("DELETE FROM rollout_task");
70	        jdbc.update("DELETE FROM release_pause_record");
71	        jdbc.update("DELETE FROM release_resume_record");
72	        jdbc.update("DELETE FROM release_order");
73	        jdbc.update("DELETE FROM device");
74	        jdbc.update("DELETE FROM idempotency_record");
75	        executor = Executors.newFixedThreadPool(8);
76	    }
