195	                            new ReceiptRequest("req-s" + seq, ReceiptResult.SUCCESS)),
196	                    (Callable<Object>) () -> releaseService.cancel(releaseId, "req-x" + seq)));
197	
198	            Object receiptResult = results.get(0);
