package com.example.starter.firmware.domain;

/**
 * 设备登记信息。
 *
 * @param deviceId          设备唯一标识
 * @param model             设备型号，登记后不可修改
 * @param currentVersion    设备当前固件版本
 * @param bucketNo          灰度分桶号，取值0~99，登记后不可修改
 * @param totalSpaceBytes   总空间字节数，正整数；NULL 为旧模式，不做暂存空间核验
 * @param currentImageBytes 当前镜像字节数，不超过总空间；NULL 为旧模式
 * @param spaceVersion      空间档案版本，从1开始，维护与首次任务终结加一；NULL 为旧模式
 */
public record Device(String deviceId, String model, String currentVersion, int bucketNo,
                     Long totalSpaceBytes, Long currentImageBytes, Integer spaceVersion) {

    /**
     * 是否登记了空间档案（版本1）。旧设备无容量字段，保留原模式。
     */
    public boolean spaceTracked() {
        return totalSpaceBytes != null;
    }
}

package com.example.starter.firmware.domain;

/**
 * 设备投放任务，同设备同发布单最多一条。
 *
 * @param id            任务ID
 * @param releaseId     所属发布单ID
 * @param deviceId      设备ID
 * @param status        任务状态
 * @param firstResult   首次回执结果（SUCCESS/FAILED），未回执为 null
 * @param reservedBytes 暂存预留字节数（压缩包+新镜像），PENDING 期间占用，任务终结时释放；旧模式为 null
 * @param peakBytes     领取时峰值字节数（当时旧镜像+包+新镜像），历史快照不漂移；旧模式为 null
 */
public record RolloutTask(long id, long releaseId, String deviceId, TaskStatus status,
                          ReceiptResult firstResult, Long reservedBytes, Long peakBytes) {
}

package com.example.starter.firmware.domain;

/**
 * 固件灰度发布单。
 *
 * @param id                      发布单ID
 * @param version                 发布单版本号，从1开始，每次扩量或人工恢复成功加一
 * @param model                   目标设备型号
 * @param fromVersion             来源固件版本
 * @param toVersion               目标固件版本，必须与来源版本不同
 * @param ratio                   投放比例，取值0~100，只增不减
 * @param status                  状态：ACTIVE 投放中，PAUSED 失败率自动暂停，CANCELLED 已取消（终态）
 * @param sampleFloor             失败率统计样本下限，取值2~100
 * @param failureThresholdPercent 失败率阈值百分比，取值1~100
 * @param monitorRound            当前监控轮次，从1开始，人工恢复后加一
 * @param roundSuccess            当前监控轮次内首次进入 SUCCESS 的任务数
 * @param roundFailed             当前监控轮次内首次进入 FAILED 的任务数
 * @param packageBytes            压缩包字节数，正整数；NULL 为旧模式，不做暂存空间核验
 * @param imageBytes              解包镜像字节数，正整数；NULL 为旧模式
 */
public record ReleaseOrder(long id, int version, String model, String fromVersion, String toVersion,
                           int ratio, ReleaseStatus status, int sampleFloor, int failureThresholdPercent,
                           int monitorRound, int roundSuccess, int roundFailed,
                           Long packageBytes, Long imageBytes) {

    /**
     * 是否登记了容量字段。旧发布无容量字段，保留原模式。
     */
    public boolean spaceTracked() {
        return packageBytes != null;
    }
}

