package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 设备登记请求。totalSpaceBytes 与 currentImageBytes 为可选空间档案（版本1）：
 * 必须成对提供，均为正整数且当前镜像不超过总空间；均不提供时保留旧模式，不做暂存空间核验。
 */
public record RegisterDeviceRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String deviceId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String currentVersion,
        @Min(0) @Max(99) int bucketNo,
        @Min(1) Long totalSpaceBytes,
        @Min(0) Long currentImageBytes) {

    /**
     * 兼容旧调用方：不登记空间档案。
     */
    public RegisterDeviceRequest(String requestId, String deviceId, String model,
                                 String currentVersion, int bucketNo) {
        this(requestId, deviceId, model, currentVersion, bucketNo, null, null);
    }
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 创建发布单请求。sampleFloor 与 failureThresholdPercent 为可选，
 * 缺省分别为 2 与 100（即仅当本轮全部失败且样本达标时才自动暂停），旧客户端不传仍可创建。
 * packageBytes 与 imageBytes 为可选容量字段：必须成对提供，均为正整数；
 * 均不提供时保留旧模式，领取不做暂存空间核验。
 */
public record CreateReleaseRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String fromVersion,
        @NotBlank @Size(max = 64) String toVersion,
        @Min(0) @Max(100) int ratio,
        @Min(2) @Max(100) Integer sampleFloor,
        @Min(1) @Max(100) Integer failureThresholdPercent,
        @Min(1) Long packageBytes,
        @Min(1) Long imageBytes) {

    public static final int DEFAULT_SAMPLE_FLOOR = 2;
    public static final int DEFAULT_FAILURE_THRESHOLD_PERCENT = 100;

    /**
     * 兼容旧调用方：不配置监控参数与容量字段时使用默认值。
     */
    public CreateReleaseRequest(String requestId, String model, String fromVersion, String toVersion, int ratio) {
        this(requestId, model, fromVersion, toVersion, ratio, null, null, null, null);
    }

    /**
     * 兼容旧调用方：配置监控参数但不登记容量字段。
     */
    public CreateReleaseRequest(String requestId, String model, String fromVersion, String toVersion,
                                int ratio, Integer sampleFloor, Integer failureThresholdPercent) {
        this(requestId, model, fromVersion, toVersion, ratio, sampleFloor, failureThresholdPercent,
                null, null);
    }

    public int effectiveSampleFloor() {
        return sampleFloor == null ? DEFAULT_SAMPLE_FLOOR : sampleFloor;
    }

    public int effectiveFailureThresholdPercent() {
        return failureThresholdPercent == null ? DEFAULT_FAILURE_THRESHOLD_PERCENT : failureThresholdPercent;
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.Device;

/**
 * 设备视图。availableBytes 为当前余量（总空间-当前镜像-活跃暂存预留），随空间占用实时变化；
 * 旧模式设备的空间字段均为 null。
 */
public record DeviceView(String deviceId, String model, String currentVersion, int bucketNo,
                         Long totalSpaceBytes, Long currentImageBytes, Integer spaceVersion,
                         Long activeReservedBytes, Long availableBytes) {

    public static DeviceView of(Device device, long activeReservedBytes) {
        Long activeReserved = device.spaceTracked() ? activeReservedBytes : null;
        Long available = device.spaceTracked()
                ? device.totalSpaceBytes() - device.currentImageBytes() - activeReservedBytes
                : null;
        return new DeviceView(device.deviceId(), device.model(), device.currentVersion(), device.bucketNo(),
                device.totalSpaceBytes(), device.currentImageBytes(), device.spaceVersion(),
                activeReserved, available);
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;

/**
 * 发布单视图。packageBytes/imageBytes 为容量字段，旧发布单为 null。
 */
public record ReleaseView(long releaseId, int version, String model, String fromVersion, String toVersion,
                          int ratio, String status, int sampleFloor, int failureThresholdPercent,
                          int monitorRound, Long packageBytes, Long imageBytes) {

    public static ReleaseView of(ReleaseOrder order) {
        return new ReleaseView(order.id(), order.version(), order.model(), order.fromVersion(),
                order.toVersion(), order.ratio(), order.status().name(), order.sampleFloor(),
                order.failureThresholdPercent(), order.monitorRound(),
                order.packageBytes(), order.imageBytes());
    }
}

package com.example.starter.firmware.api;

import com.example.starter.firmware.domain.ReleaseOrder;
import com.example.starter.firmware.domain.RolloutTask;

/**
 * 投放任务视图。peakBytes 为领取时峰值字节数（当时旧镜像+包+新镜像），
 * 历史快照不随设备当前余量漂移；旧模式任务的空间字段为 null。
 */
public record TaskView(long taskId, long releaseId, String deviceId, String status,
                       String fromVersion, String toVersion,
                       Long reservedBytes, Long peakBytes) {

    public static TaskView of(RolloutTask task, ReleaseOrder order) {
        return new TaskView(task.id(), task.releaseId(), task.deviceId(), task.status().name(),
                order.fromVersion(), order.toVersion(), task.reservedBytes(), task.peakBytes());
    }
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 设备空间维护请求：调整总空间。expectedDeviceVersion 必须等于当前空间档案版本，成功加一；
 * 调小后低于当前镜像加活跃暂存预留时返回 409 并携带当前 expectedDeviceVersion。
 */
public record UpdateDeviceSpaceRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotNull @Min(1) Long totalSpaceBytes,
        @Min(1) int expectedDeviceVersion) {
}

